def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my_def = 0
    opp_def = 0
    for me, opp in history:
        if me == 'D':
            my_def += 1
        if opp == 'D':
            opp_def += 1

    # If opponent almost always defects, defect.
    if n >= 3 and opp_def >= n - 1:
        return 'D'

    # If opponent never defects and we have defected before the last round,
    # they are an unconditional cooperator: exploit.
    if opp_def == 0 and my_def > 0:
        for me, opp in history[:-1]:
            if me == 'D':
                return 'D'

    # If opponent defects too often, defect.
    if n >= 10 and opp_def > n * 0.5:
        return 'D'

    # Probe at round 10 if both have been fully cooperative.
    if n == 10 and opp_def == 0 and my_def == 0:
        return 'D'

    last_me, last_opp = history[-1]

    # Forgiving Tit-for-Tat
    if last_opp == 'C':
        return 'C'
    else:
        if last_me == 'D':
            return 'C'
        if n >= 2 and history[-2][0] == 'D' and last_me == 'C':
            return 'C'
        return 'D'
